INSERT INTO mil_careers (position, title, official_title, service, code, code_system, home, what) VALUES
  (1, 'Navy Aviation Machinist''s Mate', 'Aviation Machinist''s Mate', 'navy', 'AD', 'navy-rating', 'maintenance', 'Maintains aircraft engines, propellers and their fuel and drive systems.'),
  (2, 'Navy Aviation Electrician''s Mate', 'Aviation Electrician''s Mate', 'navy', 'AE', 'navy-rating', 'electronics', 'Maintains aircraft electrical power, lighting and instrument systems.'),
  (3, 'Navy Aviation Structural Mechanic', 'Aviation Structural Mechanic', 'navy', 'AM', 'navy-rating', 'maintenance', 'Repairs airframes and maintains aircraft hydraulics, landing gear and flight controls.'),
  (4, 'Navy Aviation Structural Mechanic (Safety Equipment)', 'Aviation Structural Mechanic (Safety Equipment)', 'navy', 'AME', 'navy-rating', 'maintenance', 'Maintains ejection seats and aircraft oxygen, pressurization and air conditioning systems.'),
  (5, 'Navy Aviation Ordnanceman', 'Aviation Ordnanceman', 'navy', 'AO', 'navy-rating', 'assembly', 'Builds up and loads aircraft weapons and maintains the armament systems that carry them.'),
  (6, 'Navy Aviation Support Equipment Technician', 'Aviation Support Equipment Technician', 'navy', 'AS', 'navy-rating', 'maintenance', 'Repairs the ground equipment that powers, lifts and services aircraft.'),
  (7, 'Navy Aviation Electronics Technician', 'Aviation Electronics Technician', 'navy', 'AT', 'navy-rating', 'electronics', 'Maintains aircraft radar, communications, navigation and electronic warfare systems, on the aircraft and at the bench.'),
  (8, 'Navy Aircrew Survival Equipmentman', 'Aircrew Survival Equipmentman', 'navy', 'PR', 'navy-rating', 'assembly', 'Packs parachutes and inspects and repairs aircrew survival and flight equipment.'),
  (9, 'Navy Aviation Boatswain''s Mate (Launching and Recovery Equipment)', 'Aviation Boatswain''s Mate (Launching and Recovery Equipment)', 'navy', 'ABE', 'navy-rating', 'maintenance', 'Operates and maintains aircraft carrier catapults and arresting gear.'),
  (10, 'Navy Aviation Boatswain''s Mate (Fuels)', 'Aviation Boatswain''s Mate (Fuels)', 'navy', 'ABF', 'navy-rating', 'process', 'Runs and maintains aviation fuel systems and tests the fuel.'),
  (11, 'Navy Machinist''s Mate', 'Machinist''s Mate', 'navy', 'MM', 'navy-rating', 'maintenance', 'Operates and maintains ship propulsion machinery and its auxiliary systems.'),
  (12, 'Navy Engineman', 'Engineman', 'navy', 'EN', 'navy-rating', 'maintenance', 'Operates, maintains and overhauls diesel engines and auxiliary machinery.'),
  (13, 'Navy Gas Turbine Systems Technician (Mechanical)', 'Gas Turbine Systems Technician (Mechanical)', 'navy', 'GSM', 'navy-rating', 'maintenance', 'Operates and maintains ship gas turbines, reduction gears and propulsion auxiliaries.'),
  (14, 'Navy Gas Turbine Systems Technician (Electrical)', 'Gas Turbine Systems Technician (Electrical)', 'navy', 'GSE', 'navy-rating', 'automation', 'Maintains the electrical and electronic controls of gas turbine propulsion plants.'),
  (15, 'Navy Electrician''s Mate', 'Electrician''s Mate', 'navy', 'EM', 'navy-rating', 'maintenance', 'Operates and maintains ship power generation, distribution, motors and lighting.'),
  (16, 'Navy Interior Communications Electrician', 'Interior Communications Electrician', 'navy', 'IC', 'navy-rating', 'electronics', 'Maintains ship interior communication, alarm, indicating and gyrocompass systems.'),
  (17, 'Navy Hull Maintenance Technician', 'Hull Maintenance Technician', 'navy', 'HT', 'navy-rating', 'fabrication', 'Welds, brazes, cuts and fabricates ship structure, sheet metal and piping, and tests the repair.'),
  (18, 'Navy Machinery Repairman', 'Machinery Repairman', 'navy', 'MR', 'navy-rating', 'machining', 'Machines and makes replacement parts in a ship or shore machine shop.'),
  (19, 'Navy Machinist''s Mate (Nuclear Power)', 'Machinist''s Mate (Nuclear Power)', 'navy', 'MMN', 'navy-rating', 'process', 'Operates and maintains the mechanical systems of a naval reactor plant.'),
  (20, 'Navy Electrician''s Mate (Nuclear Power)', 'Electrician''s Mate (Nuclear Power)', 'navy', 'EMN', 'navy-rating', 'maintenance', 'Operates and maintains the electrical generation and distribution of a naval reactor plant.'),
  (21, 'Navy Electronics Technician (Nuclear Power)', 'Electronics Technician (Nuclear Power)', 'navy', 'ETN', 'navy-rating', 'process', 'Operates a naval reactor and maintains its instrumentation and control.'),
